/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  var D = {"views": [21, 14, 6], "calls": [3, 2, 3]};
  var st = [10, 33, 56];
  var ci = -1; for (var c = 0; c < 3; c++) if (p >= st[c]) ci = c;
  var loc = ci >= 0 ? p - st[ci] : -1;
  v.on0 = p < 10 ? 1 : 0;
  v.on1 = (ci >= 0 && loc < 6) ? 1 : 0; v.on2 = (ci >= 0 && loc >= 6 && loc < 16) ? 1 : 0; v.on3 = (ci >= 0 && loc >= 16 && p < 79) ? 1 : 0;
  for (var i = 0; i < 4; i++) v['done'+i] = (p >= (i === 0 ? 10 : 79) && p < 97) ? out : 0;
  var vc = 0, cc = 0;
  for (var c = 0; c < 3; c++) {
    var s = st[c], e = c < 2 ? st[c+1] : 94;
    var inC = p >= s && p < e;
    var fadeIn = lin([[s,0],[s+1.5,1]]), fadeOut = c < 2 ? (1 - lin([[e-1.2,0],[e,1]])) : out;
    v['cat'+c] = inC ? Math.min(fadeIn, fadeOut) : 0;
    v['ch'+c] = inC ? 1 : 0;
    v['cl'+c] = (p >= s + 1 && p < 97) ? out : 0;
    for (var k = 0; k < 4; k++) v['t'+c+'_'+k] = p >= s + 6 + k * 2.3 ? 1 : 0;
    v['n'+c] = lin([[s+16,0],[s+19,1]]);
    if (p >= s + 1) cc += D.calls[c];
    vc += Math.round(D.views[c] * lin([[s+6,0],[s+16,1]]));
  }
  v.vc = vc; v.cc = cc;
  v.fin = (p >= 79 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
